#pragma once
#include "one_layer_reference.h"
namespace upstreamreference {
inline std::map<std::string,one::Vec> forward(const one::Fixture& z,bool fp=false){std::map<std::string,one::Vec> a;auto put=[&](const std::string& n,one::Vec v){a[n]=v;return v;};auto ln=one::d(z.v.at("ln1"));
 auto q=put("up_q",one::mm(ln,one::d(z.v.at("wq")),32,64,64,false,false,fp)),k=put("up_k",one::mm(ln,one::d(z.v.at("wk")),32,64,64,false,false,fp)),v=put("up_v",one::mm(ln,one::d(z.v.at("wv")),32,64,64,false,false,fp));
 auto logits=put("up_gate_logits",one::mm(ln,one::d(z.v.at("wg")),32,2,64,false,false,fp));auto gates=logits;for(auto& g:gates)g=fp?double(float(1.f/(1.f+std::exp(-float(g))))):1/(1+std::exp(-g));put("up_gates",gates);one::Vec context(2048);
 for(unsigned h=0;h<2;++h){auto pr="h"+std::to_string(h)+"_up_";auto qh=put(pr+"q",one::split(q,h)),kh=put(pr+"k",one::split(k,h)),vh=put(pr+"v",one::split(v,h));auto scores=put(pr+"scores",one::mm(qh,kh,32,32,32,false,true,fp));auto scaled=put(pr+"scaled",one::mul(scores,{double(1.f/std::sqrt(32.f))},fp)),masked=scaled;for(unsigned row=0;row<32;++row)for(unsigned col=row+1;col<32;++col)masked[row*32+col]=fp?double(float(masked[row*32+col])-10000.f):masked[row*32+col]-10000.;put(pr+"masked",masked);auto p=put(pr+"p",one::softmax(masked,fp)),ctx=put(pr+"context",one::mm(p,vh,32,32,32,false,false,fp));one::Vec gate(32);for(unsigned row=0;row<32;++row)gate[row]=gates[row*2+h];put(pr+"gate",gate);auto gated=put(pr+"gated",one::mul(ctx,gate,fp));auto scatter=put(pr+"scatter",one::scatter(gated,h));context=one::add(context,scatter,fp);}
 put("up_context",context);auto projected=put("up_projected",one::mm(context,one::d(z.v.at("wo")),32,64,64,false,false,fp));auto x=put("up_x",one::add(one::d(z.v.at("layerinput")),projected,fp));
 // Double LN equations take double X directly. FP32 control uses the established
 // anchored oracle, with explicit FP32 store at the LN input boundary.
 one::Vec y(2048);if(fp){auto zz=z;zz.v["x"]=one::f(x);y=one::d(mmfixture::ln::anchoredFp32Oracle(one::lncase(zz),64).y);}else for(unsigned row=0;row<32;++row){double mean=0;for(unsigned c=0;c<64;++c)mean+=x[row*64+c];mean/=64;double var=0;for(unsigned c=0;c<64;++c){double delta=x[row*64+c]-mean;var+=delta*delta;}double inverse=1/std::sqrt(var/64+double(1e-5f));for(unsigned c=0;c<64;++c)y[row*64+c]=(x[row*64+c]-mean)*inverse*z.v.at("gamma")[c]+z.v.at("beta")[c];}put("y",y);
 auto ff1=put("up_ff1",one::mm(y,one::d(z.v.at("w1")),32,128,64,false,false,fp)),drelu=put("up_drelu",one::mm(one::d(z.v.at("residual")),one::d(z.v.at("w2")),32,128,64,false,true,fp));auto dff1=drelu;for(unsigned i=0;i<4096;++i)if(ff1[i]<=0)dff1[i]=0;put("up_dff1",dff1);put("up_dy",one::mm(dff1,one::d(z.v.at("w1")),32,64,128,false,true,fp));return a;
}
inline std::vector<one::Fixture> fullUpstream(const std::vector<one::Fixture>& fs){auto cases=fs;auto z=fs.at(0);z.index=fs.size();z.v["residual"].assign(2048,1.f);auto y=one::reference(z,true).at("y"),ff=one::mm(y,one::d(z.v.at("w1")),32,128,64),dr=one::mm(one::d(z.v.at("residual")),one::d(z.v.at("w2")),32,128,64,false,true);for(unsigned i=0;i<4096;++i)if(ff[i]<=0)dr[i]=0;z.v["dy"]=one::f(one::mm(dr,one::d(z.v.at("w1")),32,64,128,false,true));cases.push_back(z);return cases;}
}
